head.script:
scwin.input1_displayFormatter1 = function(value) {
    return "input1:" + value;
}
scwin.input1_oneditkeyup = function(info) {
    var logStr = "oldValue=" + info.oldValue + ", newValue=" + info.newValue + ", keyCode=" + info.keyCode;
    WebSquare.logger.printLog(logStr);
    console.log(logStr);
    log = logStr;
}
scwin.input2_displayFormatter1 = function(value) {
    return "input2:" + value;
}
scwin.input2_oneditkeyup = function(info) {
    var logStr = "oldValue=" + info.oldValue + ", newValue=" + info.newValue + ", keyCode=" + info.keyCode;
    WebSquare.logger.printLog(logStr);
    console.log(logStr);
}
scwin.input3_displayFormatter1 = function(value) {
    return "input3:" + value;
}
scwin.input3_oneditkeyup = function(info) {
    var logStr = "oldValue=" + info.oldValue + ", newValue=" + info.newValue + ", keyCode=" + info.keyCode;
    WebSquare.logger.printLog(logStr);
    console.log(logStr);
}
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    WebSquare.wUnit.getJq('#input1').simulate('key-sequence', {
        sequence: '1'
    });
}
scwin.setSimulate2 = function() {
    WebSquare.wUnit.getJq('#input1').simulate('key-sequence', {
        sequence: '2'
    });
}
scwin.setSimulate3 = function() {
    WebSquare.wUnit.getJq('#input1').simulate('key-sequence', {
        sequence: '3'
    });
}
scwin.checkVal = function() {
    return WebSquare.wUnit.getDomById($p.id + "image1").hasAttribute("usemap");
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일 실행 후 콘솔창을 실행(F12)하여 상단의 입력창에 "123"값을 입력한다.
    //1. Execute the sample file and execute the console window (F12) and input the value "123" in the upper input window.
    //Verify step 1. The oldValue, newValue, and keyCode values are displayed in the console log 
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input1').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "log == 'oldValue=1, newValue=1, keyCode=49'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "log == 'oldValue=12, newValue=12, keyCode=50'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate3()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "log == 'oldValue=123, newValue=123, keyCode=51'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.log = "";
    dataList1.setData([1, 2, 3, 4, 5, 6]);
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 20-Apr-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
